pub fn probe() -> usize {
    let mut bytes = Vec::new();
    let mut index = 0usize;
    while index < 100_000_000 {
        bytes.push((index % 251) as u8);
        index += 1;
    }
    assert_eq!(bytes.len(), 100_000_000);
    assert_eq!(bytes[0], 0u8);
    assert_eq!(bytes[bytes.len() - 1], 93u8);
    bytes.len() + bytes[0] as usize + bytes[bytes.len() - 1] as usize
}

