pub fn main(mut world: World) {
    let mut input = world.stdin();
    let bytes = input.read_to_end().unwrap();
    let mut output = world.stdout();
    output.write(format!("{}:{}:{}\n", bytes.len(), bytes[0], bytes[bytes.len() - 1]).as_bytes());
}
